) STRICT;

CREATE TABLE item (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  skill_id                     TEXT NOT NULL CHECK (length(skill_id)=36 AND substr(skill_id,15,1)='7' AND skill_id=lower(skill_id)),
  path_id                      TEXT NOT NULL CHECK (length(path_id)=36 AND substr(path_id,15,1)='7' AND path_id=lower(path_id)) REFERENCES path(id),
  code                         TEXT NOT NULL,
  type_key                     TEXT NOT NULL REFERENCES exercise_type("key"),
  state                        TEXT NOT NULL CHECK (state IN ('planned','queued','generating','in_review','ready','failed')),
  current_version_id           TEXT CHECK (length(current_version_id)=36 AND substr(current_version_id,15,1)='7' AND current_version_id=lower(current_version_id)),
  extensions                   TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extensions)),
  UNIQUE (path_id, code),
  UNIQUE (id, path_id),
  FOREIGN KEY (skill_id, path_id) REFERENCES skill (id, path_id),
  FOREIGN KEY (current_version_id, id) REFERENCES item_version (id, item_id) DEFERRABLE INITIALLY DEFERRED
) STRICT;

CREATE TABLE item_version (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  item_id                      TEXT NOT NULL CHECK (length(item_id)=36 AND substr(item_id,15,1)='7' AND item_id=lower(item_id)) REFERENCES item(id),
  version_no                   INTEGER NOT NULL CHECK (version_no >= 1),
  version_hash                 TEXT NOT NULL CHECK (length(version_hash)=64 AND version_hash NOT GLOB '*[^0-9a-f]*'),
  lang                         TEXT NOT NULL CHECK (length(lang) BETWEEN 2 AND 35),
  translation_of_version_hash  TEXT CHECK (length(translation_of_version_hash)=64 AND translation_of_version_hash NOT GLOB '*[^0-9a-f]*'),
  derived_from_version_id      TEXT CHECK (length(derived_from_version_id)=36 AND substr(derived_from_version_id,15,1)='7' AND derived_from_version_id=lower(derived_from_version_id)) REFERENCES item_version(id),
  difficulty                   TEXT NOT NULL CHECK (difficulty IN ('introductory','foundational','intermediate','advanced','expert')),
  payload                      TEXT NOT NULL CHECK (json_valid(payload)),
  support                      TEXT NOT NULL CHECK (json_valid(support)),
  origin_lesson_version_id     TEXT CHECK (length(origin_lesson_version_id)=36 AND substr(origin_lesson_version_id,15,1)='7' AND origin_lesson_version_id=lower(origin_lesson_version_id)) REFERENCES lesson_version(id),
  resets_review                INTEGER NOT NULL CHECK (resets_review IN (0,1)),
  status                       TEXT NOT NULL CHECK (status IN ('in_review','passed','rejected')),
  published_at                 TEXT CHECK (published_at = strftime('%Y-%m-%dT%H:%M:%fZ', published_at)),
  created_at                   TEXT NOT NULL CHECK (created_at = strftime('%Y-%m-%dT%H:%M:%fZ', created_at)),
  authorship                   TEXT NOT NULL CHECK (authorship IN ('generated','human','human_edited','translated')),
  acquired_via                 TEXT NOT NULL CHECK (acquired_via IN ('local','import','fork')),
  author_kind                  TEXT NOT NULL CHECK (author_kind IN ('system','learner','curator','external')),
  author_ref                   TEXT,
  produced_by_stage_run_id     TEXT CHECK (length(produced_by_stage_run_id)=36 AND substr(produced_by_stage_run_id,15,1)='7' AND produced_by_stage_run_id=lower(produced_by_stage_run_id)) REFERENCES stage_run(id),
  upstream                     TEXT CHECK (json_valid(upstream)),
  licence                      TEXT,
  personal_inputs              INTEGER NOT NULL CHECK (personal_inputs IN (0,1)),
  UNIQUE (item_id, version_no),
  UNIQUE (id, item_id)
) STRICT;

