CREATE TABLE learning_event (
  server_seq                   INTEGER PRIMARY KEY AUTOINCREMENT,
  id                           TEXT NOT NULL UNIQUE CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  payload_hash                 TEXT NOT NULL CHECK (length(payload_hash)=64 AND payload_hash NOT GLOB '*[^0-9a-f]*'),
  learner_id                   TEXT NOT NULL CHECK (length(learner_id)=36 AND substr(learner_id,15,1)='7' AND learner_id=lower(learner_id)) REFERENCES learner(id),
  type                         TEXT NOT NULL REFERENCES event_type("key"),
  type_version                 INTEGER NOT NULL CHECK (type_version >= 1),
  device_id                    TEXT NOT NULL CHECK (length(device_id)=36 AND substr(device_id,15,1)='7' AND device_id=lower(device_id)) REFERENCES device(id),
  device_at                    TEXT NOT NULL CHECK (device_at = strftime('%Y-%m-%dT%H:%M:%fZ', device_at)),
  server_at                    TEXT NOT NULL CHECK (server_at = strftime('%Y-%m-%dT%H:%M:%fZ', server_at)),
  tz                           TEXT NOT NULL CHECK (length(tz) BETWEEN 1 AND 64),
  learning_day                 TEXT NOT NULL CHECK (learning_day = date(learning_day)),
  item_version_id              TEXT CHECK (length(item_version_id)=36 AND substr(item_version_id,15,1)='7' AND item_version_id=lower(item_version_id)) REFERENCES item_version(id),
  lesson_version_id            TEXT CHECK (length(lesson_version_id)=36 AND substr(lesson_version_id,15,1)='7' AND lesson_version_id=lower(lesson_version_id)) REFERENCES lesson_version(id),
  rendition_version_id         TEXT CHECK (length(rendition_version_id)=36 AND substr(rendition_version_id,15,1)='7' AND rendition_version_id=lower(rendition_version_id)) REFERENCES rendition_version(id),
  attempt_id                   TEXT CHECK (length(attempt_id)=36 AND substr(attempt_id,15,1)='7' AND attempt_id=lower(attempt_id)),
  skill_id                     TEXT CHECK (length(skill_id)=36 AND substr(skill_id,15,1)='7' AND skill_id=lower(skill_id)) REFERENCES skill(id),
  payload                      TEXT NOT NULL CHECK (json_valid(payload)),
  CHECK (item_version_id IS payload ->> '$.item_version_id'),
  CHECK (lesson_version_id IS payload ->> '$.lesson_version_id'),
  CHECK (rendition_version_id IS payload ->> '$.rendition_version_id'),
  CHECK (attempt_id IS payload ->> '$.attempt_id'),
  CHECK (skill_id IS payload ->> '$.skill_id')
) STRICT;

CREATE TABLE learning_objective (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  skill_id                     TEXT NOT NULL CHECK (length(skill_id)=36 AND substr(skill_id,15,1)='7' AND skill_id=lower(skill_id)),
  path_id                      TEXT NOT NULL CHECK (length(path_id)=36 AND substr(path_id,15,1)='7' AND path_id=lower(path_id)) REFERENCES path(id),
  code                         TEXT NOT NULL,
  statement                    TEXT NOT NULL,
  bloom_level                  TEXT,
  position                     INTEGER NOT NULL CHECK (position >= 0),
  extensions                   TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extensions)),
  archived_at                  TEXT CHECK (archived_at = strftime('%Y-%m-%dT%H:%M:%fZ', archived_at)),
  UNIQUE (path_id, code),
  FOREIGN KEY (skill_id, path_id) REFERENCES skill (id, path_id)
) STRICT;

CREATE TABLE lesson (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  skill_id                     TEXT NOT NULL CHECK (length(skill_id)=36 AND substr(skill_id,15,1)='7' AND skill_id=lower(skill_id)),
  path_id                      TEXT NOT NULL CHECK (length(path_id)=36 AND substr(path_id,15,1)='7' AND path_id=lower(path_id)) REFERENCES path(id),
  code                         TEXT NOT NULL,
  kind                         TEXT NOT NULL CHECK (kind IN ('core','remedial','requested')),
  position                     INTEGER NOT NULL CHECK (position >= 0),
  state                        TEXT NOT NULL CHECK (state IN ('planned','queued','generating','in_review','ready','failed')),
  current_version_id           TEXT CHECK (length(current_version_id)=36 AND substr(current_version_id,15,1)='7' AND current_version_id=lower(current_version_id)),
  extensions                   TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extensions)),
  UNIQUE (path_id, code),
  UNIQUE (id, path_id),
  FOREIGN KEY (skill_id, path_id) REFERENCES skill (id, path_id),
  FOREIGN KEY (current_version_id, id) REFERENCES lesson_version (id, lesson_id) DEFERRABLE INITIALLY DEFERRED
) STRICT;

CREATE TABLE lesson_request (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  learner_id                   TEXT NOT NULL CHECK (length(learner_id)=36 AND substr(learner_id,15,1)='7' AND learner_id=lower(learner_id)) REFERENCES learner(id),
  path_id                      TEXT NOT NULL CHECK (length(path_id)=36 AND substr(path_id,15,1)='7' AND path_id=lower(path_id)) REFERENCES path(id),
  skill_id                     TEXT CHECK (length(skill_id)=36 AND substr(skill_id,15,1)='7' AND skill_id=lower(skill_id)) REFERENCES skill(id),
  prompt                       TEXT NOT NULL,
  links                        TEXT NOT NULL CHECK (json_valid(links)),
  status                       TEXT NOT NULL CHECK (status IN ('pending','running','done','failed','cancelled')),
  lesson_id                    TEXT CHECK (length(lesson_id)=36 AND substr(lesson_id,15,1)='7' AND lesson_id=lower(lesson_id)) REFERENCES lesson(id),
  error                        TEXT,
  created_at                   TEXT NOT NULL CHECK (created_at = strftime('%Y-%m-%dT%H:%M:%fZ', created_at)),
  updated_at                   TEXT NOT NULL CHECK (updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', updated_at))
) STRICT;

CREATE TABLE lesson_search_doc (
  docid                        INTEGER PRIMARY KEY NOT NULL,
  lesson_version_id            TEXT NOT NULL UNIQUE CHECK (length(lesson_version_id)=36 AND substr(lesson_version_id,15,1)='7' AND lesson_version_id=lower(lesson_version_id)) REFERENCES lesson_version(id),
  title                        TEXT NOT NULL,
  body                         TEXT NOT NULL
) STRICT;

CREATE TABLE lesson_version (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  lesson_id                    TEXT NOT NULL CHECK (length(lesson_id)=36 AND substr(lesson_id,15,1)='7' AND lesson_id=lower(lesson_id)) REFERENCES lesson(id),
  version_no                   INTEGER NOT NULL CHECK (version_no >= 1),
  version_hash                 TEXT NOT NULL CHECK (length(version_hash)=64 AND version_hash NOT GLOB '*[^0-9a-f]*'),
  lang                         TEXT NOT NULL CHECK (length(lang) BETWEEN 2 AND 35),
  translation_of_version_hash  TEXT CHECK (length(translation_of_version_hash)=64 AND translation_of_version_hash NOT GLOB '*[^0-9a-f]*'),
  derived_from_version_id      TEXT CHECK (length(derived_from_version_id)=36 AND substr(derived_from_version_id,15,1)='7' AND derived_from_version_id=lower(derived_from_version_id)) REFERENCES lesson_version(id),
  title                        TEXT NOT NULL,
  body                         TEXT NOT NULL CHECK (json_valid(body)),
  est_minutes                  INTEGER NOT NULL CHECK (est_minutes >= 0),
  status                       TEXT NOT NULL CHECK (status IN ('in_review','passed','rejected')),
  published_at                 TEXT CHECK (published_at = strftime('%Y-%m-%dT%H:%M:%fZ', published_at)),
  created_at                   TEXT NOT NULL CHECK (created_at = strftime('%Y-%m-%dT%H:%M:%fZ', created_at)),
  authorship                   TEXT NOT NULL CHECK (authorship IN ('generated','human','human_edited','translated')),
  acquired_via                 TEXT NOT NULL CHECK (acquired_via IN ('local','import','fork')),
  author_kind                  TEXT NOT NULL CHECK (author_kind IN ('system','learner','curator','external')),
  author_ref                   TEXT,
  produced_by_stage_run_id     TEXT CHECK (length(produced_by_stage_run_id)=36 AND substr(produced_by_stage_run_id,15,1)='7' AND produced_by_stage_run_id=lower(produced_by_stage_run_id)) REFERENCES stage_run(id),
  upstream                     TEXT CHECK (json_valid(upstream)),
  licence                      TEXT,
  personal_inputs              INTEGER NOT NULL CHECK (personal_inputs IN (0,1)),
  UNIQUE (lesson_id, version_no),
  UNIQUE (id, lesson_id)
) STRICT;

CREATE TABLE lesson_version_objective (
  lesson_version_id            TEXT NOT NULL CHECK (length(lesson_version_id)=36 AND substr(lesson_version_id,15,1)='7' AND lesson_version_id=lower(lesson_version_id)) REFERENCES lesson_version(id),
  objective_id                 TEXT NOT NULL CHECK (length(objective_id)=36 AND substr(objective_id,15,1)='7' AND objective_id=lower(objective_id)) REFERENCES learning_objective(id),
  "role"                       TEXT NOT NULL CHECK ("role" IN ('primary','secondary')),
  PRIMARY KEY (lesson_version_id, objective_id)
) STRICT, WITHOUT ROWID;

CREATE TABLE lesson_version_source (
  lesson_version_id            TEXT NOT NULL CHECK (length(lesson_version_id)=36 AND substr(lesson_version_id,15,1)='7' AND lesson_version_id=lower(lesson_version_id)) REFERENCES lesson_version(id),
  source_id                    TEXT NOT NULL CHECK (length(source_id)=36 AND substr(source_id,15,1)='7' AND source_id=lower(source_id)) REFERENCES source(id),
  locator                      TEXT,
  block_ids                    TEXT CHECK (json_valid(block_ids)),
  PRIMARY KEY (lesson_version_id, source_id)
) STRICT, WITHOUT ROWID;

CREATE TABLE merge_conflict (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  head_kind                    TEXT NOT NULL REFERENCES entity_kind_ref("key"),
  head_id                      TEXT NOT NULL CHECK (length(head_id)=36 AND substr(head_id,15,1)='7' AND head_id=lower(head_id)),
  local_version_id             TEXT NOT NULL CHECK (length(local_version_id)=36 AND substr(local_version_id,15,1)='7' AND local_version_id=lower(local_version_id)),
  incoming_version_hash        TEXT NOT NULL CHECK (length(incoming_version_hash)=64 AND incoming_version_hash NOT GLOB '*[^0-9a-f]*'),
  status                       TEXT NOT NULL CHECK (status IN ('open','kept_local','took_incoming')),
  created_at                   TEXT NOT NULL CHECK (created_at = strftime('%Y-%m-%dT%H:%M:%fZ', created_at)),
  resolved_at                  TEXT CHECK (resolved_at = strftime('%Y-%m-%dT%H:%M:%fZ', resolved_at))
) STRICT;

CREATE TABLE message (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  conversation_id              TEXT NOT NULL CHECK (length(conversation_id)=36 AND substr(conversation_id,15,1)='7' AND conversation_id=lower(conversation_id)) REFERENCES conversation(id),
  "role"                       TEXT NOT NULL CHECK ("role" IN ('learner','tutor','system')),
  status                       TEXT NOT NULL CHECK (status IN ('queued','streaming','done','failed','withdrawn')),
  content                      TEXT NOT NULL CHECK (json_valid(content)),
  context                      TEXT NOT NULL CHECK (json_valid(context)),
  policy                       TEXT NOT NULL CHECK (policy IN ('free','lesson','practice','test_locked','test_hints','review','setup')),
  stage_run_id                 TEXT CHECK (length(stage_run_id)=36 AND substr(stage_run_id,15,1)='7' AND stage_run_id=lower(stage_run_id)) REFERENCES stage_run(id),
  leak_check                   TEXT CHECK (leak_check IN ('pass','warn','fail')),
  guard                        TEXT CHECK (guard IN ('template','checked','blocked')),
  created_at                   TEXT NOT NULL CHECK (created_at = strftime('%Y-%m-%dT%H:%M:%fZ', created_at)),
  completed_at                 TEXT CHECK (completed_at = strftime('%Y-%m-%dT%H:%M:%fZ', completed_at))
) STRICT;

CREATE TABLE model_capability (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  adapter                      TEXT NOT NULL,
  model                        TEXT NOT NULL,
  declared                     TEXT NOT NULL CHECK (json_valid(declared)),
  measured                     TEXT CHECK (json_valid(measured)),
  measured_at                  TEXT CHECK (measured_at = strftime('%Y-%m-%dT%H:%M:%fZ', measured_at)),
  supported_roles              TEXT NOT NULL CHECK (json_valid(supported_roles))
) STRICT;

CREATE TABLE note (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  learner_id                   TEXT NOT NULL CHECK (length(learner_id)=36 AND substr(learner_id,15,1)='7' AND learner_id=lower(learner_id)) REFERENCES learner(id),
  rendition_version_id         TEXT CHECK (length(rendition_version_id)=36 AND substr(rendition_version_id,15,1)='7' AND rendition_version_id=lower(rendition_version_id)) REFERENCES rendition_version(id),
  t_s                          REAL CHECK (t_s >= 0),
  anchor                       TEXT CHECK (json_valid(anchor)),
  "text"                       TEXT NOT NULL,
  sent_message_id              TEXT CHECK (length(sent_message_id)=36 AND substr(sent_message_id,15,1)='7' AND sent_message_id=lower(sent_message_id)) REFERENCES message(id),
  created_at                   TEXT NOT NULL CHECK (created_at = strftime('%Y-%m-%dT%H:%M:%fZ', created_at)),
  updated_at                   TEXT NOT NULL CHECK (updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', updated_at)),
  CHECK ((rendition_version_id IS NULL) = (t_s IS NULL)),
  CHECK (NOT (rendition_version_id IS NOT NULL AND anchor IS NOT NULL))
) STRICT;

CREATE TABLE nudge (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  learner_id                   TEXT NOT NULL CHECK (length(learner_id)=36 AND substr(learner_id,15,1)='7' AND learner_id=lower(learner_id)) REFERENCES learner(id),
  path_id                      TEXT CHECK (length(path_id)=36 AND substr(path_id,15,1)='7' AND path_id=lower(path_id)) REFERENCES path(id),
  trigger                      TEXT NOT NULL CHECK (trigger IN ('repeated_error','fast_guessing','unsent_notes','failed_test')),
  params                       TEXT NOT NULL CHECK (json_valid(params)),
  status                       TEXT NOT NULL CHECK (status IN ('shown','dismissed','accepted','expired')),
  created_at                   TEXT NOT NULL CHECK (created_at = strftime('%Y-%m-%dT%H:%M:%fZ', created_at)),
  decided_at                   TEXT CHECK (decided_at = strftime('%Y-%m-%dT%H:%M:%fZ', decided_at))
) STRICT;

CREATE TABLE package (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  package_uid                  TEXT NOT NULL UNIQUE,
  title                        TEXT NOT NULL,
  origin_author                TEXT NOT NULL,
  licence                      TEXT NOT NULL,
  parent_package_digest        TEXT CHECK (length(parent_package_digest)=64 AND parent_package_digest NOT GLOB '*[^0-9a-f]*')
) STRICT;

CREATE TABLE package_record (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  package_id                   TEXT NOT NULL CHECK (length(package_id)=36 AND substr(package_id,15,1)='7' AND package_id=lower(package_id)) REFERENCES package(id),
  direction                    TEXT NOT NULL CHECK (direction IN ('export','import')),
  profile                      TEXT NOT NULL CHECK (profile IN ('structure','full','custom')),
  format_version               TEXT NOT NULL,
  content_version              TEXT NOT NULL,
  package_digest               TEXT NOT NULL CHECK (length(package_digest)=64 AND package_digest NOT GLOB '*[^0-9a-f]*'),
  signature_ref                TEXT,
  manifest                     TEXT NOT NULL CHECK (json_valid(manifest)),
  file_hash                    TEXT NOT NULL CHECK (length(file_hash)=64 AND file_hash NOT GLOB '*[^0-9a-f]*'),
  path_id                      TEXT CHECK (length(path_id)=36 AND substr(path_id,15,1)='7' AND path_id=lower(path_id)) REFERENCES path(id),
  "at"                         TEXT NOT NULL CHECK ("at" = strftime('%Y-%m-%dT%H:%M:%fZ', "at"))
) STRICT;

CREATE TABLE path (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  code                         TEXT NOT NULL UNIQUE,
  learner_id                   TEXT NOT NULL CHECK (length(learner_id)=36 AND substr(learner_id,15,1)='7' AND learner_id=lower(learner_id)) REFERENCES learner(id),
  title                        TEXT NOT NULL,
  subject                      TEXT NOT NULL,
  goal                         TEXT NOT NULL,
  goal_type                    TEXT NOT NULL CHECK (goal_type IN ('exam','practical','understanding','curiosity')),
  target_date                  TEXT CHECK (target_date = date(target_date)),
  difficulty                   TEXT NOT NULL CHECK (difficulty IN ('introductory','foundational','intermediate','advanced','expert')),
  content_lang                 TEXT NOT NULL CHECK (length(content_lang) BETWEEN 2 AND 35),
  status                       TEXT NOT NULL CHECK (status IN ('draft','active','paused','completed','archived')),
  authorship                   TEXT NOT NULL CHECK (authorship IN ('generated','human','human_edited','translated')),
  acquired_via                 TEXT NOT NULL CHECK (acquired_via IN ('local','import','fork')),
  package_id                   TEXT CHECK (length(package_id)=36 AND substr(package_id,15,1)='7' AND package_id=lower(package_id)) REFERENCES package(id),
  translation_of_path_id       TEXT CHECK (length(translation_of_path_id)=36 AND substr(translation_of_path_id,15,1)='7' AND translation_of_path_id=lower(translation_of_path_id)) REFERENCES path(id),
  structure_version            INTEGER NOT NULL CHECK (structure_version >= 0),
  licence                      TEXT NOT NULL,
  authors                      TEXT NOT NULL CHECK (json_valid(authors)),
  extensions                   TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extensions)),
  created_at                   TEXT NOT NULL CHECK (created_at = strftime('%Y-%m-%dT%H:%M:%fZ', created_at)),
  updated_at                   TEXT NOT NULL CHECK (updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', updated_at))
) STRICT;

CREATE TABLE path_change (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  path_id                      TEXT NOT NULL CHECK (length(path_id)=36 AND substr(path_id,15,1)='7' AND path_id=lower(path_id)) REFERENCES path(id),
  base_structure_version       INTEGER NOT NULL CHECK (base_structure_version >= 0),
  structure_version            INTEGER NOT NULL CHECK (structure_version >= 0),
  ops                          TEXT NOT NULL CHECK (json_valid(ops)),
  origin                       TEXT NOT NULL CHECK (origin IN ('learner','proposal','import','generation')),
  proposal_id                  TEXT CHECK (length(proposal_id)=36 AND substr(proposal_id,15,1)='7' AND proposal_id=lower(proposal_id)) REFERENCES proposal(id),
  device_id                    TEXT CHECK (length(device_id)=36 AND substr(device_id,15,1)='7' AND device_id=lower(device_id)) REFERENCES device(id),
  "at"                         TEXT NOT NULL CHECK ("at" = strftime('%Y-%m-%dT%H:%M:%fZ', "at")),
  CHECK (structure_version > base_structure_version)
) STRICT;

CREATE TABLE prompt_template (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  "key"                        TEXT NOT NULL,
  version                      INTEGER NOT NULL CHECK (version >= 1),
  lang                         TEXT NOT NULL CHECK (length(lang) BETWEEN 2 AND 35),
  body                         TEXT NOT NULL,
  body_hash                    TEXT NOT NULL CHECK (length(body_hash)=64 AND body_hash NOT GLOB '*[^0-9a-f]*'),
  input_schema                 TEXT NOT NULL CHECK (json_valid(input_schema)),
  output_schema                TEXT NOT NULL CHECK (json_valid(output_schema)),
  created_at                   TEXT NOT NULL CHECK (created_at = strftime('%Y-%m-%dT%H:%M:%fZ', created_at)),
  UNIQUE ("key", version, lang)
) STRICT;

CREATE TABLE proposal (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  learner_id                   TEXT NOT NULL CHECK (length(learner_id)=36 AND substr(learner_id,15,1)='7' AND learner_id=lower(learner_id)) REFERENCES learner(id),
  path_id                      TEXT NOT NULL CHECK (length(path_id)=36 AND substr(path_id,15,1)='7' AND path_id=lower(path_id)) REFERENCES path(id),
  kind                         TEXT NOT NULL CHECK (kind IN ('add_lesson','change_prerequisites','extra_review','change_difficulty','other')),
  rationale                    TEXT NOT NULL,
  change                       TEXT NOT NULL CHECK (json_valid(change)),
  origin                       TEXT NOT NULL CHECK (origin IN ('tutor','system')),
  created_at                   TEXT NOT NULL CHECK (created_at = strftime('%Y-%m-%dT%H:%M:%fZ', created_at)),
  expires_at                   TEXT CHECK (expires_at = strftime('%Y-%m-%dT%H:%M:%fZ', expires_at))
) STRICT;

CREATE TABLE publication (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  head_kind                    TEXT NOT NULL REFERENCES entity_kind_ref("key"),
  head_id                      TEXT NOT NULL CHECK (length(head_id)=36 AND substr(head_id,15,1)='7' AND head_id=lower(head_id)),
  version_id                   TEXT NOT NULL CHECK (length(version_id)=36 AND substr(version_id,15,1)='7' AND version_id=lower(version_id)),
  "at"                         TEXT NOT NULL CHECK ("at" = strftime('%Y-%m-%dT%H:%M:%fZ', "at")),
  "by"                         TEXT NOT NULL CHECK ("by" IN ('gate','learner','import'))
) STRICT;

CREATE TABLE quality_check (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  subject_kind                 TEXT NOT NULL REFERENCES entity_kind_ref("key"),
  subject_version_id           TEXT NOT NULL CHECK (length(subject_version_id)=36 AND substr(subject_version_id,15,1)='7' AND subject_version_id=lower(subject_version_id)),
  "check"                      TEXT NOT NULL REFERENCES check_kind("key"),
  verdict                      TEXT NOT NULL CHECK (verdict IN ('pass','warn','fail')),
  fix_round                    INTEGER NOT NULL CHECK (fix_round >= 0),
  independent                  INTEGER CHECK (independent IN (0,1)),
  details                      TEXT NOT NULL CHECK (json_valid(details)),
  stage_run_id                 TEXT CHECK (length(stage_run_id)=36 AND substr(stage_run_id,15,1)='7' AND stage_run_id=lower(stage_run_id)) REFERENCES stage_run(id),
  "at"                         TEXT NOT NULL CHECK ("at" = strftime('%Y-%m-%dT%H:%M:%fZ', "at"))
) STRICT;

CREATE TABLE rendition (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  lesson_id                    TEXT NOT NULL CHECK (length(lesson_id)=36 AND substr(lesson_id,15,1)='7' AND lesson_id=lower(lesson_id)) REFERENCES lesson(id),
  kind                         TEXT NOT NULL CHECK (kind IN ('reading','video','slides','audio')),
  state                        TEXT NOT NULL CHECK (state IN ('planned','queued','generating','in_review','ready','failed')),
  current_version_id           TEXT CHECK (length(current_version_id)=36 AND substr(current_version_id,15,1)='7' AND current_version_id=lower(current_version_id)),
  UNIQUE (id, lesson_id),
  FOREIGN KEY (current_version_id, id) REFERENCES rendition_version (id, rendition_id) DEFERRABLE INITIALLY DEFERRED
) STRICT;

CREATE TABLE rendition_asset (
  rendition_version_id         TEXT NOT NULL CHECK (length(rendition_version_id)=36 AND substr(rendition_version_id,15,1)='7' AND rendition_version_id=lower(rendition_version_id)) REFERENCES rendition_version(id),
  "role"                       TEXT NOT NULL CHECK ("role" IN ('video','poster','audio','subtitles','image','attachment')),
  lang                         TEXT NOT NULL CHECK (length(lang) BETWEEN 2 AND 35),
  recipe_hash                  TEXT NOT NULL CHECK (length(recipe_hash)=64 AND recipe_hash NOT GLOB '*[^0-9a-f]*'),
  asset_hash                   TEXT NOT NULL CHECK (length(asset_hash)=64 AND asset_hash NOT GLOB '*[^0-9a-f]*') REFERENCES asset(hash),
  PRIMARY KEY (rendition_version_id, "role", lang)
) STRICT, WITHOUT ROWID;

CREATE TABLE rendition_version (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  rendition_id                 TEXT NOT NULL CHECK (length(rendition_id)=36 AND substr(rendition_id,15,1)='7' AND rendition_id=lower(rendition_id)) REFERENCES rendition(id),
  version_no                   INTEGER NOT NULL CHECK (version_no >= 1),
  version_hash                 TEXT NOT NULL CHECK (length(version_hash)=64 AND version_hash NOT GLOB '*[^0-9a-f]*'),
  lesson_version_id            TEXT NOT NULL CHECK (length(lesson_version_id)=36 AND substr(lesson_version_id,15,1)='7' AND lesson_version_id=lower(lesson_version_id)) REFERENCES lesson_version(id),
  lang                         TEXT NOT NULL CHECK (length(lang) BETWEEN 2 AND 35),
  renderer                     TEXT NOT NULL,
  spec_kind                    TEXT NOT NULL CHECK (spec_kind IN ('agent_code','rendered')),
  spec                         TEXT NOT NULL CHECK (json_valid(spec)),
  narration                    TEXT CHECK (json_valid(narration)),
  theme_id                     TEXT CHECK (length(theme_id)=36 AND substr(theme_id,15,1)='7' AND theme_id=lower(theme_id)) REFERENCES theme(id),
  voice                        TEXT,
  duration_s                   REAL CHECK (duration_s >= 0),
  derived_from_version_id      TEXT CHECK (length(derived_from_version_id)=36 AND substr(derived_from_version_id,15,1)='7' AND derived_from_version_id=lower(derived_from_version_id)) REFERENCES rendition_version(id),
  status                       TEXT NOT NULL CHECK (status IN ('in_review','passed','rejected')),
  published_at                 TEXT CHECK (published_at = strftime('%Y-%m-%dT%H:%M:%fZ', published_at)),
  created_at                   TEXT NOT NULL CHECK (created_at = strftime('%Y-%m-%dT%H:%M:%fZ', created_at)),
  authorship                   TEXT NOT NULL CHECK (authorship IN ('generated','human','human_edited','translated')),
  acquired_via                 TEXT NOT NULL CHECK (acquired_via IN ('local','import','fork')),
  author_kind                  TEXT NOT NULL CHECK (author_kind IN ('system','learner','curator','external')),
  author_ref                   TEXT,
  produced_by_stage_run_id     TEXT CHECK (length(produced_by_stage_run_id)=36 AND substr(produced_by_stage_run_id,15,1)='7' AND produced_by_stage_run_id=lower(produced_by_stage_run_id)) REFERENCES stage_run(id),
  upstream                     TEXT CHECK (json_valid(upstream)),
  licence                      TEXT,
  personal_inputs              INTEGER NOT NULL CHECK (personal_inputs IN (0,1)),
  UNIQUE (rendition_id, version_no),
  UNIQUE (id, rendition_id)
) STRICT;

CREATE TABLE response (
  response_event_id            TEXT PRIMARY KEY NOT NULL CHECK (length(response_event_id)=36 AND substr(response_event_id,15,1)='7' AND response_event_id=lower(response_event_id)) REFERENCES learning_event(id),
  attempt_id                   TEXT NOT NULL CHECK (length(attempt_id)=36 AND substr(attempt_id,15,1)='7' AND attempt_id=lower(attempt_id)),
  item_version_id              TEXT NOT NULL CHECK (length(item_version_id)=36 AND substr(item_version_id,15,1)='7' AND item_version_id=lower(item_version_id)) REFERENCES item_version(id),
  answered_at                  TEXT NOT NULL CHECK (answered_at = strftime('%Y-%m-%dT%H:%M:%fZ', answered_at)),
  help_kind                    TEXT NOT NULL CHECK (help_kind IN ('none','hint','solution','tutor')),
  hint_depth                   INTEGER NOT NULL CHECK (hint_depth >= 0),
  ms_to_answer                 INTEGER CHECK (ms_to_answer >= 0),
  latest_grade_event_id        TEXT CHECK (length(latest_grade_event_id)=36 AND substr(latest_grade_event_id,15,1)='7' AND latest_grade_event_id=lower(latest_grade_event_id)) REFERENCES learning_event(id),
  score                        REAL CHECK (score BETWEEN 0 AND 1),
  grading_method               TEXT CHECK (grading_method IN ('exact','rule','model','self')),
  algo_version                 INTEGER NOT NULL CHECK (algo_version >= 1),
  inputs_hash                  TEXT NOT NULL CHECK (length(inputs_hash)=64 AND inputs_hash NOT GLOB '*[^0-9a-f]*'),
  rebuilt_at                   TEXT NOT NULL CHECK (rebuilt_at = strftime('%Y-%m-%dT%H:%M:%fZ', rebuilt_at))
) STRICT;

CREATE TABLE review_state (
  learner_id                   TEXT NOT NULL CHECK (length(learner_id)=36 AND substr(learner_id,15,1)='7' AND learner_id=lower(learner_id)) REFERENCES learner(id),
  item_id                      TEXT NOT NULL CHECK (length(item_id)=36 AND substr(item_id,15,1)='7' AND item_id=lower(item_id)) REFERENCES item(id),
  facet                        TEXT NOT NULL DEFAULT '',
  scheduler                    TEXT NOT NULL,
  state                        TEXT NOT NULL CHECK (json_valid(state)),
  due_at                       TEXT NOT NULL CHECK (due_at = strftime('%Y-%m-%dT%H:%M:%fZ', due_at)),
  last_review_at               TEXT CHECK (last_review_at = strftime('%Y-%m-%dT%H:%M:%fZ', last_review_at)),
  algo_version                 INTEGER NOT NULL CHECK (algo_version >= 1),
  inputs_hash                  TEXT NOT NULL CHECK (length(inputs_hash)=64 AND inputs_hash NOT GLOB '*[^0-9a-f]*'),
  rebuilt_at                   TEXT NOT NULL CHECK (rebuilt_at = strftime('%Y-%m-%dT%H:%M:%fZ', rebuilt_at)),
  PRIMARY KEY (learner_id, item_id, facet)
) STRICT;

CREATE TABLE schedule (
  "key"                        TEXT PRIMARY KEY NOT NULL,
  next_run_at                  TEXT NOT NULL CHECK (next_run_at = strftime('%Y-%m-%dT%H:%M:%fZ', next_run_at)),
  tz                           TEXT NOT NULL CHECK (length(tz) BETWEEN 1 AND 64),
  last_run_at                  TEXT CHECK (last_run_at = strftime('%Y-%m-%dT%H:%M:%fZ', last_run_at))
) STRICT;

CREATE TABLE setting_audit (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  "key"                        TEXT NOT NULL,
  old                          TEXT CHECK (json_valid(old)),
  new                          TEXT NOT NULL CHECK (json_valid(new)),
  device_id                    TEXT CHECK (length(device_id)=36 AND substr(device_id,15,1)='7' AND device_id=lower(device_id)) REFERENCES device(id),
  "at"                         TEXT NOT NULL CHECK ("at" = strftime('%Y-%m-%dT%H:%M:%fZ', "at"))
) STRICT;

CREATE TABLE setting_value (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  "key"                        TEXT NOT NULL,
  scope                        TEXT NOT NULL CHECK (scope IN ('installation','learner','path','lesson')),
  scope_ref                    TEXT CHECK (length(scope_ref)=36 AND substr(scope_ref,15,1)='7' AND scope_ref=lower(scope_ref)),
  value                        TEXT NOT NULL CHECK (json_valid(value)),
  data_class                   TEXT NOT NULL CHECK (data_class IN ('P','F','C','K','S','O')) CHECK (data_class IN ('K','F')),
  updated_at                   TEXT NOT NULL CHECK (updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', updated_at)),
  updated_by_device_id         TEXT CHECK (length(updated_by_device_id)=36 AND substr(updated_by_device_id,15,1)='7' AND updated_by_device_id=lower(updated_by_device_id)) REFERENCES device(id),
  UNIQUE ("key", scope, scope_ref)
) STRICT;

CREATE TABLE skill (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  branch_id                    TEXT NOT NULL CHECK (length(branch_id)=36 AND substr(branch_id,15,1)='7' AND branch_id=lower(branch_id)),
  path_id                      TEXT NOT NULL CHECK (length(path_id)=36 AND substr(path_id,15,1)='7' AND path_id=lower(path_id)) REFERENCES path(id),
  code                         TEXT NOT NULL,
  title                        TEXT NOT NULL,
  summary                      TEXT NOT NULL,
  position                     INTEGER NOT NULL CHECK (position >= 0),
  mastery_threshold            REAL CHECK (mastery_threshold BETWEEN 0 AND 1),
  optional                     INTEGER NOT NULL CHECK (optional IN (0,1)),
  merged_into_skill_id         TEXT CHECK (length(merged_into_skill_id)=36 AND substr(merged_into_skill_id,15,1)='7' AND merged_into_skill_id=lower(merged_into_skill_id)) REFERENCES skill(id),
  extensions                   TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extensions)),
  archived_at                  TEXT CHECK (archived_at = strftime('%Y-%m-%dT%H:%M:%fZ', archived_at)),
  UNIQUE (path_id, code),
  UNIQUE (id, path_id),
  FOREIGN KEY (branch_id, path_id) REFERENCES branch (id, path_id)
) STRICT;

CREATE TABLE skill_prerequisite (
  skill_id                     TEXT NOT NULL CHECK (length(skill_id)=36 AND substr(skill_id,15,1)='7' AND skill_id=lower(skill_id)),
  requires_skill_id            TEXT NOT NULL CHECK (length(requires_skill_id)=36 AND substr(requires_skill_id,15,1)='7' AND requires_skill_id=lower(requires_skill_id)),
  path_id                      TEXT NOT NULL CHECK (length(path_id)=36 AND substr(path_id,15,1)='7' AND path_id=lower(path_id)) REFERENCES path(id),
  PRIMARY KEY (skill_id, requires_skill_id),
  FOREIGN KEY (skill_id, path_id) REFERENCES skill (id, path_id),
  FOREIGN KEY (requires_skill_id, path_id) REFERENCES skill (id, path_id),
  CHECK (skill_id <> requires_skill_id)
) STRICT, WITHOUT ROWID;

CREATE TABLE skill_progress (
  learner_id                   TEXT NOT NULL CHECK (length(learner_id)=36 AND substr(learner_id,15,1)='7' AND learner_id=lower(learner_id)) REFERENCES learner(id),
  skill_id                     TEXT NOT NULL CHECK (length(skill_id)=36 AND substr(skill_id,15,1)='7' AND skill_id=lower(skill_id)) REFERENCES skill(id),
  state                        TEXT NOT NULL CHECK (state IN ('locked','available','in_progress','mastered','needs_review')),
  mastery                      REAL NOT NULL CHECK (mastery BETWEEN 0 AND 1),
  evidence_count               INTEGER NOT NULL CHECK (evidence_count >= 0),
  last_activity_at             TEXT CHECK (last_activity_at = strftime('%Y-%m-%dT%H:%M:%fZ', last_activity_at)),
  algo_version                 INTEGER NOT NULL CHECK (algo_version >= 1),
  inputs_hash                  TEXT NOT NULL CHECK (length(inputs_hash)=64 AND inputs_hash NOT GLOB '*[^0-9a-f]*'),
  rebuilt_at                   TEXT NOT NULL CHECK (rebuilt_at = strftime('%Y-%m-%dT%H:%M:%fZ', rebuilt_at)),
  PRIMARY KEY (learner_id, skill_id)
) STRICT;

CREATE TABLE source (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  "key"                        TEXT NOT NULL UNIQUE,
  kind                         TEXT NOT NULL CHECK (kind IN ('web','document','book','video','upload','other')),
  title                        TEXT NOT NULL,
  url                          TEXT,
  accessed_at                  TEXT CHECK (accessed_at = strftime('%Y-%m-%dT%H:%M:%fZ', accessed_at)),
  published_at                 TEXT CHECK (published_at = date(published_at)),
  citation                     TEXT NOT NULL CHECK (json_valid(citation)),
  data_class                   TEXT NOT NULL CHECK (data_class IN ('P','F','C','K','S','O')) CHECK (data_class IN ('C','F')),
  extensions                   TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(extensions))
) STRICT;

CREATE TABLE stage_input (
  stage_run_id                 TEXT NOT NULL CHECK (length(stage_run_id)=36 AND substr(stage_run_id,15,1)='7' AND stage_run_id=lower(stage_run_id)) REFERENCES stage_run(id),
  input_output_hash            TEXT NOT NULL CHECK (length(input_output_hash)=64 AND input_output_hash NOT GLOB '*[^0-9a-f]*'),
  "role"                       TEXT NOT NULL,
  PRIMARY KEY (stage_run_id, input_output_hash, "role")
) STRICT, WITHOUT ROWID;

CREATE TABLE stage_kind (
  "key"                        TEXT PRIMARY KEY NOT NULL
) STRICT, WITHOUT ROWID;

CREATE TABLE stage_output (
  hash                         TEXT PRIMARY KEY NOT NULL CHECK (length(hash)=64 AND hash NOT GLOB '*[^0-9a-f]*'),
  schema_id                    TEXT NOT NULL,
  schema_version               INTEGER NOT NULL CHECK (schema_version >= 1),
  raw                          TEXT NOT NULL CHECK (json_valid(raw)),
  parsed                       TEXT CHECK (json_valid(parsed)),
  data_class                   TEXT NOT NULL CHECK (data_class IN ('P','F','C','K','S','O')) CHECK (data_class IN ('C','P','F','O')),
  created_at                   TEXT NOT NULL CHECK (created_at = strftime('%Y-%m-%dT%H:%M:%fZ', created_at))
) STRICT;

CREATE TABLE stage_run (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  job_id                       TEXT NOT NULL CHECK (length(job_id)=36 AND substr(job_id,15,1)='7' AND job_id=lower(job_id)) REFERENCES generation_job(id),
  stage                        TEXT NOT NULL REFERENCES stage_kind("key"),
  input_manifest               TEXT NOT NULL CHECK (json_valid(input_manifest)),
  input_hash                   TEXT NOT NULL CHECK (length(input_hash)=64 AND input_hash NOT GLOB '*[^0-9a-f]*'),
  output_hash                  TEXT CHECK (length(output_hash)=64 AND output_hash NOT GLOB '*[^0-9a-f]*'),
  status                       TEXT NOT NULL CHECK (status IN ('queued','waiting_resource','running','succeeded','failed','cancelled')),
  resource                     TEXT,
  adapter                      TEXT NOT NULL,
  adapter_version              TEXT NOT NULL,
  model_requested              TEXT,
  model_resolved               TEXT,
  provider                     TEXT,
  reasoning_effort             TEXT,
  "role"                       TEXT,
  cache_hit_of_stage_run_id    TEXT CHECK (length(cache_hit_of_stage_run_id)=36 AND substr(cache_hit_of_stage_run_id,15,1)='7' AND cache_hit_of_stage_run_id=lower(cache_hit_of_stage_run_id)) REFERENCES stage_run(id),
  data_class                   TEXT NOT NULL CHECK (data_class IN ('P','F','C','K','S','O')) CHECK (data_class IN ('C','P','F','O')),
  started_at                   TEXT CHECK (started_at = strftime('%Y-%m-%dT%H:%M:%fZ', started_at)),
  finished_at                  TEXT CHECK (finished_at = strftime('%Y-%m-%dT%H:%M:%fZ', finished_at)),
  error                        TEXT
) STRICT;

CREATE TABLE theme (
  id                           TEXT PRIMARY KEY NOT NULL CHECK (length(id)=36 AND substr(id,15,1)='7' AND id=lower(id)),
  kind                         TEXT NOT NULL CHECK (kind IN ('ui','video')),
  name                         TEXT NOT NULL,
  tokens                       TEXT NOT NULL CHECK (json_valid(tokens)),
  inherits_ui_theme_id         TEXT CHECK (length(inherits_ui_theme_id)=36 AND substr(inherits_ui_theme_id,15,1)='7' AND inherits_ui_theme_id=lower(inherits_ui_theme_id)) REFERENCES theme(id),
  built_in                     INTEGER NOT NULL CHECK (built_in IN (0,1))
) STRICT;

CREATE TABLE watch_coverage (
  learner_id                   TEXT NOT NULL CHECK (length(learner_id)=36 AND substr(learner_id,15,1)='7' AND learner_id=lower(learner_id)) REFERENCES learner(id),
  rendition_version_id         TEXT NOT NULL CHECK (length(rendition_version_id)=36 AND substr(rendition_version_id,15,1)='7' AND rendition_version_id=lower(rendition_version_id)) REFERENCES rendition_version(id),
  covered                      TEXT NOT NULL CHECK (json_valid(covered)),
  share                        REAL NOT NULL CHECK (share BETWEEN 0 AND 1),
  algo_version                 INTEGER NOT NULL CHECK (algo_version >= 1),
  inputs_hash                  TEXT NOT NULL CHECK (length(inputs_hash)=64 AND inputs_hash NOT GLOB '*[^0-9a-f]*'),
  rebuilt_at                   TEXT NOT NULL CHECK (rebuilt_at = strftime('%Y-%m-%dT%H:%M:%fZ', rebuilt_at)),
  PRIMARY KEY (learner_id, rendition_version_id)
) STRICT;

CREATE TABLE xp_daily (
  learner_id                   TEXT NOT NULL CHECK (length(learner_id)=36 AND substr(learner_id,15,1)='7' AND learner_id=lower(learner_id)) REFERENCES learner(id),
  learning_day                 TEXT NOT NULL CHECK (learning_day = date(learning_day)),
  xp                           INTEGER NOT NULL CHECK (xp >= 0),
  sessions                     INTEGER NOT NULL CHECK (sessions >= 0),
  streak_len                   INTEGER NOT NULL CHECK (streak_len >= 0),
  grace_used                   INTEGER NOT NULL CHECK (grace_used >= 0),
  algo_version                 INTEGER NOT NULL CHECK (algo_version >= 1),
  inputs_hash                  TEXT NOT NULL CHECK (length(inputs_hash)=64 AND inputs_hash NOT GLOB '*[^0-9a-f]*'),
  rebuilt_at                   TEXT NOT NULL CHECK (rebuilt_at = strftime('%Y-%m-%dT%H:%M:%fZ', rebuilt_at)),
  PRIMARY KEY (learner_id, learning_day)
) STRICT;

CREATE TRIGGER item_version_no_delete BEFORE DELETE ON item_version
WHEN NOT EXISTS (SELECT 1 FROM erasure_guard)
BEGIN SELECT RAISE(ABORT, 'item_version rows are deleted only by erasure'); END;

CREATE TRIGGER item_version_immutable BEFORE UPDATE ON item_version
WHEN NOT EXISTS (SELECT 1 FROM erasure_guard) AND (OLD.id IS NOT NEW.id OR OLD.item_id IS NOT NEW.item_id OR OLD.version_no IS NOT NEW.version_no OR OLD.version_hash IS NOT NEW.version_hash OR OLD.lang IS NOT NEW.lang OR OLD.translation_of_version_hash IS NOT NEW.translation_of_version_hash OR OLD.derived_from_version_id IS NOT NEW.derived_from_version_id OR OLD.difficulty IS NOT NEW.difficulty OR OLD.payload IS NOT NEW.payload OR OLD.support IS NOT NEW.support OR OLD.origin_lesson_version_id IS NOT NEW.origin_lesson_version_id OR OLD.resets_review IS NOT NEW.resets_review OR OLD.created_at IS NOT NEW.created_at OR OLD.authorship IS NOT NEW.authorship OR OLD.acquired_via IS NOT NEW.acquired_via OR OLD.author_kind IS NOT NEW.author_kind OR OLD.author_ref IS NOT NEW.author_ref OR OLD.produced_by_stage_run_id IS NOT NEW.produced_by_stage_run_id OR OLD.upstream IS NOT NEW.upstream OR OLD.licence IS NOT NEW.licence OR OLD.personal_inputs IS NOT NEW.personal_inputs
  OR (OLD.status IS NOT NEW.status AND (OLD.status <> 'in_review' OR NEW.status = 'in_review'))
  OR (OLD.published_at IS NOT NULL AND OLD.published_at IS NOT NEW.published_at))
BEGIN SELECT RAISE(ABORT, 'item_version is immutable except status and published_at, set once'); END;

CREATE TRIGGER item_current_passed_insert BEFORE INSERT ON item
WHEN NEW.current_version_id IS NOT NULL
  AND (SELECT status FROM item_version WHERE id = NEW.current_version_id) IS NOT 'passed'
BEGIN SELECT RAISE(ABORT, 'item.current_version_id must point to a passed version'); END;

CREATE TRIGGER item_current_passed_update BEFORE UPDATE OF current_version_id ON item
WHEN NEW.current_version_id IS NOT NULL
  AND (SELECT status FROM item_version WHERE id = NEW.current_version_id) IS NOT 'passed'
BEGIN SELECT RAISE(ABORT, 'item.current_version_id must point to a passed version'); END;

CREATE TRIGGER item_version_lang BEFORE INSERT ON item_version
WHEN NEW.lang IS NOT (SELECT p.content_lang FROM item i JOIN path p ON p.id = i.path_id WHERE i.id = NEW.item_id)
BEGIN SELECT RAISE(ABORT, 'item_version.lang must equal path.content_lang'); END;

CREATE TRIGGER learning_event_no_update BEFORE UPDATE ON learning_event
BEGIN SELECT RAISE(ABORT, 'learning_event is append-only'); END;

CREATE TRIGGER learning_event_no_delete BEFORE DELETE ON learning_event
WHEN NOT EXISTS (SELECT 1 FROM erasure_guard)
BEGIN SELECT RAISE(ABORT, 'learning_event rows are deleted only by erasure'); END;

CREATE TRIGGER lesson_version_no_delete BEFORE DELETE ON lesson_version
WHEN NOT EXISTS (SELECT 1 FROM erasure_guard)
BEGIN SELECT RAISE(ABORT, 'lesson_version rows are deleted only by erasure'); END;

CREATE TRIGGER lesson_version_immutable BEFORE UPDATE ON lesson_version
WHEN NOT EXISTS (SELECT 1 FROM erasure_guard) AND (OLD.id IS NOT NEW.id OR OLD.lesson_id IS NOT NEW.lesson_id OR OLD.version_no IS NOT NEW.version_no OR OLD.version_hash IS NOT NEW.version_hash OR OLD.lang IS NOT NEW.lang OR OLD.translation_of_version_hash IS NOT NEW.translation_of_version_hash OR OLD.derived_from_version_id IS NOT NEW.derived_from_version_id OR OLD.title IS NOT NEW.title OR OLD.body IS NOT NEW.body OR OLD.est_minutes IS NOT NEW.est_minutes OR OLD.created_at IS NOT NEW.created_at OR OLD.authorship IS NOT NEW.authorship OR OLD.acquired_via IS NOT NEW.acquired_via OR OLD.author_kind IS NOT NEW.author_kind OR OLD.author_ref IS NOT NEW.author_ref OR OLD.produced_by_stage_run_id IS NOT NEW.produced_by_stage_run_id OR OLD.upstream IS NOT NEW.upstream OR OLD.licence IS NOT NEW.licence OR OLD.personal_inputs IS NOT NEW.personal_inputs
  OR (OLD.status IS NOT NEW.status AND (OLD.status <> 'in_review' OR NEW.status = 'in_review'))
  OR (OLD.published_at IS NOT NULL AND OLD.published_at IS NOT NEW.published_at))
BEGIN SELECT RAISE(ABORT, 'lesson_version is immutable except status and published_at, set once'); END;

CREATE TRIGGER lesson_current_passed_insert BEFORE INSERT ON lesson
WHEN NEW.current_version_id IS NOT NULL
  AND (SELECT status FROM lesson_version WHERE id = NEW.current_version_id) IS NOT 'passed'
BEGIN SELECT RAISE(ABORT, 'lesson.current_version_id must point to a passed version'); END;

CREATE TRIGGER lesson_current_passed_update BEFORE UPDATE OF current_version_id ON lesson
WHEN NEW.current_version_id IS NOT NULL
  AND (SELECT status FROM lesson_version WHERE id = NEW.current_version_id) IS NOT 'passed'
BEGIN SELECT RAISE(ABORT, 'lesson.current_version_id must point to a passed version'); END;

CREATE TRIGGER lesson_version_lang BEFORE INSERT ON lesson_version
WHEN NEW.lang IS NOT (SELECT p.content_lang FROM lesson l JOIN path p ON p.id = l.path_id WHERE l.id = NEW.lesson_id)
BEGIN SELECT RAISE(ABORT, 'lesson_version.lang must equal path.content_lang'); END;

CREATE TRIGGER rendition_version_no_delete BEFORE DELETE ON rendition_version
WHEN NOT EXISTS (SELECT 1 FROM erasure_guard)
BEGIN SELECT RAISE(ABORT, 'rendition_version rows are deleted only by erasure'); END;

CREATE TRIGGER rendition_version_immutable BEFORE UPDATE ON rendition_version
WHEN NOT EXISTS (SELECT 1 FROM erasure_guard) AND (OLD.id IS NOT NEW.id OR OLD.rendition_id IS NOT NEW.rendition_id OR OLD.version_no IS NOT NEW.version_no OR OLD.version_hash IS NOT NEW.version_hash OR OLD.lesson_version_id IS NOT NEW.lesson_version_id OR OLD.lang IS NOT NEW.lang OR OLD.renderer IS NOT NEW.renderer OR OLD.spec_kind IS NOT NEW.spec_kind OR OLD.spec IS NOT NEW.spec OR OLD.narration IS NOT NEW.narration OR OLD.theme_id IS NOT NEW.theme_id OR OLD.voice IS NOT NEW.voice OR OLD.duration_s IS NOT NEW.duration_s OR OLD.derived_from_version_id IS NOT NEW.derived_from_version_id OR OLD.created_at IS NOT NEW.created_at OR OLD.authorship IS NOT NEW.authorship OR OLD.acquired_via IS NOT NEW.acquired_via OR OLD.author_kind IS NOT NEW.author_kind OR OLD.author_ref IS NOT NEW.author_ref OR OLD.produced_by_stage_run_id IS NOT NEW.produced_by_stage_run_id OR OLD.upstream IS NOT NEW.upstream OR OLD.licence IS NOT NEW.licence OR OLD.personal_inputs IS NOT NEW.personal_inputs
  OR (OLD.status IS NOT NEW.status AND (OLD.status <> 'in_review' OR NEW.status = 'in_review'))
  OR (OLD.published_at IS NOT NULL AND OLD.published_at IS NOT NEW.published_at))
BEGIN SELECT RAISE(ABORT, 'rendition_version is immutable except status and published_at, set once'); END;

CREATE TRIGGER rendition_current_passed_insert BEFORE INSERT ON rendition
WHEN NEW.current_version_id IS NOT NULL
  AND (SELECT status FROM rendition_version WHERE id = NEW.current_version_id) IS NOT 'passed'
BEGIN SELECT RAISE(ABORT, 'rendition.current_version_id must point to a passed version'); END;

CREATE TRIGGER rendition_current_passed_update BEFORE UPDATE OF current_version_id ON rendition
WHEN NEW.current_version_id IS NOT NULL
  AND (SELECT status FROM rendition_version WHERE id = NEW.current_version_id) IS NOT 'passed'
BEGIN SELECT RAISE(ABORT, 'rendition.current_version_id must point to a passed version'); END;

CREATE TRIGGER rendition_version_lang BEFORE INSERT ON rendition_version
WHEN NEW.lang IS NOT (SELECT p.content_lang FROM rendition r JOIN lesson l ON l.id = r.lesson_id JOIN path p ON p.id = l.path_id WHERE r.id = NEW.rendition_id)
BEGIN SELECT RAISE(ABORT, 'rendition_version.lang must equal path.content_lang'); END;

CREATE INDEX generation_job_runnable ON generation_job (next_attempt_at)
WHERE status IN ('queued','waiting_resource');
CREATE UNIQUE INDEX stage_run_inflight ON stage_run (input_hash)
WHERE status IN ('queued','waiting_resource','running');
CREATE INDEX stage_run_cache ON stage_run (input_hash) WHERE status = 'succeeded';
CREATE INDEX learning_event_item_version ON learning_event (item_version_id)
WHERE item_version_id IS NOT NULL;
CREATE INDEX learning_event_learner_order ON learning_event (learner_id, device_at, id);
CREATE INDEX asset_live ON asset (kind, created_at) WHERE evicted_at IS NULL;
CREATE INDEX message_streaming ON message (conversation_id) WHERE status = 'streaming';
CREATE INDEX message_conversation ON message (conversation_id, created_at);
CREATE INDEX asset_ref_owner ON asset_ref (owner_kind, owner_id);
CREATE TRIGGER rendition_version_same_lesson BEFORE INSERT ON rendition_version
WHEN NOT EXISTS (SELECT 1 FROM lesson_version lv JOIN rendition r ON r.lesson_id = lv.lesson_id
                 WHERE r.id = NEW.rendition_id AND lv.id = NEW.lesson_version_id)
BEGIN SELECT RAISE(ABORT, 'rendition_version must present a version of its own lesson'); END;
CREATE VIRTUAL TABLE lesson_fts USING fts5(
  title, body, content='lesson_search_doc', content_rowid='docid',
  tokenize='unicode61 remove_diacritics 2', prefix='2 3'
);
INSERT INTO lesson_fts (lesson_fts, rank) VALUES ('secure-delete', 1);
CREATE TRIGGER lesson_search_doc_ai AFTER INSERT ON lesson_search_doc BEGIN
  INSERT INTO lesson_fts (rowid, title, body) VALUES (NEW.docid, NEW.title, NEW.body);
END;
CREATE TRIGGER lesson_search_doc_ad AFTER DELETE ON lesson_search_doc BEGIN
  INSERT INTO lesson_fts (lesson_fts, rowid, title, body) VALUES ('delete', OLD.docid, OLD.title, OLD.body);
END;
CREATE TRIGGER lesson_search_doc_au AFTER UPDATE ON lesson_search_doc BEGIN
  INSERT INTO lesson_fts (lesson_fts, rowid, title, body) VALUES ('delete', OLD.docid, OLD.title, OLD.body);
  INSERT INTO lesson_fts (rowid, title, body) VALUES (NEW.docid, NEW.title, NEW.body);
END;

